(function(root){'use strict';
const node=typeof module!=='undefined',S=node?require('./save.js'):root.ArcSave,C=node?require('./crew.js'):root.ArcCrew,R=node?require('./campaign-run.js'):root.ArcCampaignRun,W=node?require('./weapons.js'):root.ArcWeapons;
function prepare(data,cleared){if(!Number.isInteger(cleared)||cleared<0||cleared>100)throw RangeError('Clear count must be0–100');const next=JSON.parse(JSON.stringify(data)),stage=Math.min(100,cleared+1),old=R.decode(data.chapterRun);next.cleared=cleared;next.unlockedCharacterIds=C.normalize([...data.unlockedCharacterIds,...C.joinedAt(cleared)]);next.joinedCharacterIds=C.normalize([...data.joinedCharacterIds,...C.joinedAt(cleared)]);next.unlockedWeaponIds=[...new Set([...data.unlockedWeaponIds,...Object.entries(W.coreUnlocks).filter(([,at])=>cleared>=at).map(([id])=>id)])];next.pendingRecruit=null;next.journal={...data.journal,pendingMovie:null};next.journeyStarted=true;next.onboarding={...data.onboarding,step:'done'};next.difficultyConfirmed=true;next.chapterRun=cleared===100?null:R.checkpoint(stage,old&&old.chapter===R.chapter(stage)?old.inventory:{});return S.decode(JSON.stringify(next));}
const api={prepare,passwordMatches:value=>value==='master'};if(node)module.exports=api;else root.ArcMasterProgress=api;
})(globalThis);
